// The Adventure Book, written into patchouli_books/adventure_book on every launch.
// Patchouli only finds books in that folder, and a CurseForge profile export can leave the folder out.
// Writing it from here (startup scripts run before Patchouli looks for books) means every player who has
// the pack's kubejs folder has the book. Generated by tools/book_installer_js.py from the book itself.

const FT_BOOK_FILES = {"book.json":{"name":"Adventure Book","landing_text":"How this world works, and the way to the End.$(br2)$(l)Purple words$() lead somewhere. Hover an item for $(l)R$() and $(l)U$().","version":2,"creative_tab":"minecraft:tools_and_utilities","use_resource_pack":true,"show_progress":false,"use_blocky_font":true,"book_texture":"kubejs:textures/gui/adventure_book.png","crafting_texture":"kubejs:textures/gui/adventure_crafting.png","model":"patchouli:book_purple","subtitle":"Adventures of Fairytale","text_color":"2A1A10","header_color":"4A2418","nameplate_color":"E8C77A","link_color":"7A2FA8","link_hover_color":"C062F0","progress_bar_color":"C9A35A","progress_bar_background":"4A2A40"},"en_us/categories/bees.json":{"name":"Bees","description":"Productive Bees and the Bumblezone.","icon":"minecraft:honeycomb","sortnum":5},"en_us/categories/bosses.json":{"name":"Bosses","description":"Every major boss, where it lives and how to start the fight.","icon":"minecraft:wither_skeleton_skull","sortnum":13},"en_us/categories/crafting.json":{"name":"Tinkers and Create","description":"Tools that grow with you, and machines.","icon":"tconstruct:pickaxe","sortnum":4},"en_us/categories/creatures.json":{"name":"Creatures","description":"What lives out there.","icon":"alexsmobs:animal_dictionary","sortnum":10},"en_us/categories/dragons.json":{"name":"Dragons","description":"Ice and Fire.","icon":"iceandfire:dragonscales_blue","sortnum":12},"en_us/categories/end.json":{"name":"The End","description":"End Remastered and the final fight.","icon":"minecraft:ender_eye","sortnum":14},"en_us/categories/food.json":{"name":"Food and Fishing","description":"Farmer's Delight, its add-ons, Aquaculture and Tide.","icon":"farmersdelight:cooking_pot","sortnum":3},"en_us/categories/gear.json":{"name":"Weapons and Armor","description":"Where your gear comes from and how to improve it.","icon":"minecraft:iron_sword","sortnum":7},"en_us/categories/magic.json":{"name":"Magic","description":"Iron's Spells, Forbidden & Arcanus, Hexerei and Mystical Agriculture.","icon":"irons_spellbooks:arcane_essence","sortnum":9},"en_us/categories/notes.json":{"name":"Apollo's Notes","description":"Torn pages, and what they say.","icon":"minecraft:writable_book","sortnum":0},"en_us/categories/realms.json":{"name":"Other Realms","description":"Twilight Forest, the Otherside, Alex's Caves and the Aether.","icon":"twilightforest:magic_map","sortnum":11},"en_us/categories/travel.json":{"name":"Travel and Storage","description":"Getting around and keeping your things.","icon":"waystones:waystone","sortnum":2},"en_us/categories/trinkets.json":{"name":"Trinkets and Relics","description":"Artifacts, Relics and other worn items.","icon":"relics:magic_mirror","sortnum":8},"en_us/categories/villages.json":{"name":"Villages and Exploring","description":"Bounties, traders, dungeons, structures and archaeology.","icon":"minecraft:bell","sortnum":6},"en_us/categories/world.json":{"name":"How the World Works","description":"Difficulty, seasons, food and skills.","icon":"sereneseasons:calendar","sortnum":1},"en_us/templates/fairytale_mixer.json":{"components":[{"type":"patchouli:header","text":"#title","x":-1,"y":-1},{"type":"patchouli:item","item":"#item","x":50,"y":14,"framed":true,"link_recipe":true},{"type":"patchouli:item","item":"#lower","x":26,"y":40},{"type":"patchouli:item","item":"#lower","x":8,"y":58},{"type":"patchouli:item","item":"#crystal","x":26,"y":58},{"type":"patchouli:item","item":"#lower","x":44,"y":58},{"type":"patchouli:item","item":"#lower","x":26,"y":76},{"type":"patchouli:item","item":"create:mechanical_mixer","x":70,"y":49},{"type":"patchouli:item","item":"create:basin","x":70,"y":67},{"type":"patchouli:item","item":"#heat","x":70,"y":85},{"type":"patchouli:item","item":"#out","x":96,"y":58},{"type":"patchouli:text","text":"#text","x":0,"y":104,"max_width":116}]},"en_us/entries/creatures/chaos.json":{"name":"Born in Chaos","icon":"born_in_chaos_v1:dark_metal_ingot","category":"patchouli:creatures","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Born in Chaos fills the nights with worse things than zombies. What they drop makes $(l:creatures/chaos#dark_metal_ingot)Dark Metal$(/l), charms and elixirs.$(br2)$(l)Seeds of Chaos$() brew into the base for its elixirs."},{"type":"patchouli:spotlight","item":"born_in_chaos_v1:dark_metal_ingot","text":"","link_recipe":true,"anchor":"dark_metal_ingot"}]},"en_us/entries/creatures/mobs.json":{"name":"Wildlife","icon":"alexsmobs:animal_dictionary","category":"patchouli:creatures","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The wilds are crowded now: dozens of animals from $(l)Alex's Mobs$(), with more from $(l)Naturalist$(), $(l)Critters and Companions$() and others, spread across a great many new biomes. Some are worth catching. Some are worth avoiding."},{"type":"patchouli:spotlight","item":"alexsmobs:animal_dictionary","text":"Read it to learn about every Alex's Mobs creature.","link_recipe":true,"anchor":"animal_dictionary"},{"type":"patchouli:crafting","recipe":"alexsmobs:animal_dictionary","title":"Further Reading","text":"The $(l)Animal Dictionary$() goes deeper.","anchor":"animal_dictionary_2"}],"extra_recipe_mappings":{"alexsmobs:animal_dictionary":0}},"en_us/entries/villages/archaeology.json":{"name":"Archaeology","icon":"minecraft:brush","category":"patchouli:villages","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Brushing goes deeper here. Better brushes dig faster. You'll turn up fossils, some of which do more than sit there, and $(l:villages/archaeology#artifact_shards)artifact shards$(/l) worth identifying at an $(l:villages/archaeology#archeology_table)Archeology Table$(/l)."},{"type":"patchouli:spotlight","item":"betterarcheology:archeology_table","text":"","link_recipe":true,"anchor":"archeology_table"},{"type":"patchouli:spotlight","item":"betterarcheology:artifact_shards","text":"","link_recipe":true,"anchor":"artifact_shards"}]},"en_us/entries/villages/bounties.json":{"name":"Bounties","icon":"minecraft:bell","category":"patchouli:villages","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Village $(l:villages/bounties#bountyboard)Bounty Boards$(/l) post jobs: things to fetch, things to kill, all on a timer. $(l:villages/bounties#decree)Decrees$(/l) pinned to the board decide what kind."},{"type":"patchouli:spotlight","item":"bountiful:bountyboard","text":"","link_recipe":true,"anchor":"bountyboard"},{"type":"patchouli:spotlight","item":"bountiful:decree","text":"","link_recipe":true,"anchor":"decree"}]},"en_us/entries/villages/loot.json":{"name":"Dungeons and Loot","icon":"minecraft:chest","category":"patchouli:villages","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Dungeons, towers and ruins are scattered everywhere, and most of them are worth clearing. Each player gets their own loot from every chest.$(br2)Not every chest is a chest. Some bite."}]},"en_us/entries/villages/structures.json":{"name":"Structures","icon":"explorerscompass:explorerscompass","category":"patchouli:villages","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The world is crowded with places to explore: redesigned dungeons and temples, sprawling underground crawls, roadside taverns, and the lairs of the $(l:bosses/mowzie)Mowzie's bosses$(/l).$(br2)An $(l:villages/structures#explorerscompass)Explorer's Compass$(/l) finds whatever you're looking for."},{"type":"patchouli:spotlight","item":"explorerscompass:explorerscompass","text":"Pick a structure and it points the way.","link_recipe":true,"anchor":"explorerscompass"}],"extra_recipe_mappings":{"explorerscompass:explorerscompass":0}},"en_us/entries/villages/traders.json":{"name":"Traders","icon":"minecraft:emerald","category":"patchouli:villages","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Villages have guards now, and you can hand them better gear. Villagers have names. Chefs trade food.$(br2)Deep underground you may meet a $(l)Goblin Trader$(). Don't hit him."}]},"en_us/entries/end/crown.json":{"name":"The King's Crown","icon":"kubejs:kings_crown","category":"patchouli:end","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Twelve eyes open the End. They don't finish the story.$(br2)The Crown was broken into four pieces, each kept by one of the hardest foes in the world:"},{"type":"patchouli:text","text":"$(li)$(l:end/crown#crown_band)Band of the Crown$(/l): the Underworld Knight$(li)$(l:end/crown#crown_jewel)Jewel of the Crown$(/l): the Void Blossom$(li)$(l:end/crown#crown_crest)Crest of the Crown$(/l): the Wither$(li)$(l:end/crown#crown_setting)Setting of the Crown$(/l): the Harbinger"},{"type":"patchouli:text","text":"The $(l:end/crown#dragons_heart)Dragon's Heart$(/l) binds them into $(l:end/crown#kings_crown)The King's Crown$(/l). Whoever wears it will understand why it was broken."},{"type":"patchouli:spotlight","item":"kubejs:crown_band","text":"From the Underworld Knight.","link_recipe":true,"anchor":"crown_band"},{"type":"patchouli:spotlight","item":"kubejs:crown_jewel","text":"From the Void Blossom.","link_recipe":true,"anchor":"crown_jewel"},{"type":"patchouli:spotlight","item":"kubejs:crown_crest","text":"From the Wither.","link_recipe":true,"anchor":"crown_crest"},{"type":"patchouli:spotlight","item":"kubejs:crown_setting","text":"From the Harbinger.","link_recipe":true,"anchor":"crown_setting"},{"type":"patchouli:spotlight","item":"kubejs:dragons_heart","text":"From the Ender Dragon.","link_recipe":true,"anchor":"dragons_heart"},{"type":"patchouli:crafting","recipe":"kubejs:kings_crown","anchor":"kings_crown"}],"extra_recipe_mappings":{"kubejs:crown_band":0,"kubejs:crown_jewel":0,"kubejs:crown_crest":0,"kubejs:crown_setting":0,"kubejs:dragons_heart":0,"kubejs:kings_crown":0}},"en_us/entries/end/dragon.json":{"name":"The Last Fight","icon":"minecraft:dragon_head","category":"patchouli:end","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Twelve eyes in the frame and the portal opens.$(br2)This dragon is far worse than the one you remember. Bring your best, bring healing, and have a plan for the crystals."},{"type":"patchouli:text","text":"Its death tips the world into $(l)Master$() difficulty, and there are older things out on the End islands."}]},"en_us/entries/end/eyes.json":{"name":"End Remastered","icon":"endrem:old_eye","category":"patchouli:end","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The End portal won't take Eyes of Ender here. It needs $(l)twelve$() special eyes, and each one is held by a boss. They're in no chest, no recipe. An eye that comes any other way crumbles in your hand."},{"type":"patchouli:text","text":"Everyone who helps bring the boss down gets one.$(br2)$(li)$(l:end/eyes#lost_eye)Lost Eye$(/l): the Ferrous Wroughtnaut$(li)$(l:end/eyes#cold_eye)Cold Eye$(/l): the Frostmaw$(li)$(l:end/eyes#rogue_eye)Rogue Eye$(/l): Umvuthi$(li)$(l:end/eyes#witch_eye)Witch Eye$(/l): Sir Pumpkinhead$(li)$(l:end/eyes#undead_eye)Undead Eye$(/l): the Dead King"},{"type":"patchouli:text","text":"$(li)$(l:end/eyes#black_eye)Black Eye$(/l): Captain Cornelia"},{"type":"patchouli:spotlight","item":"endrem:lost_eye","text":"From the Ferrous Wroughtnaut.","link_recipe":true,"anchor":"lost_eye"},{"type":"patchouli:spotlight","item":"endrem:cold_eye","text":"From the Frostmaw.","link_recipe":true,"anchor":"cold_eye"},{"type":"patchouli:spotlight","item":"endrem:rogue_eye","text":"From Umvuthi.","link_recipe":true,"anchor":"rogue_eye"},{"type":"patchouli:spotlight","item":"endrem:witch_eye","text":"From Sir Pumpkinhead.","link_recipe":true,"anchor":"witch_eye"},{"type":"patchouli:spotlight","item":"endrem:undead_eye","text":"From the Dead King.","link_recipe":true,"anchor":"undead_eye"},{"type":"patchouli:spotlight","item":"endrem:black_eye","text":"From Captain Cornelia.","link_recipe":true,"anchor":"black_eye"}],"extra_recipe_mappings":{"endrem:lost_eye":0,"endrem:cold_eye":0,"endrem:rogue_eye":0,"endrem:witch_eye":0,"endrem:undead_eye":0,"endrem:black_eye":0}},"en_us/entries/end/eyes2.json":{"name":"The Other Six","icon":"endrem:nether_eye","category":"patchouli:end","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l:end/eyes2#magical_eye)Magical Eye$(/l): the Twilight Lich$(li)$(l:end/eyes2#evil_eye)Evil Eye$(/l): the Night Lich$(li)$(l:end/eyes2#exotic_eye)Exotic Eye$(/l): the Sandworm$(li)$(l:end/eyes2#old_eye)Old Eye$(/l): the Ancient Remnant$(li)$(l:end/eyes2#guardian_eye)Guardian Eye$(/l): the Leviathan"},{"type":"patchouli:text","text":"$(li)$(l:end/eyes2#nether_eye)Nether Eye$(/l): the Netherite Monstrosity$(br2)$(l:notes/start)Apollo's Notes$(/l) lead from one to the next."},{"type":"patchouli:spotlight","item":"endrem:magical_eye","text":"From the Twilight Lich.","link_recipe":true,"anchor":"magical_eye"},{"type":"patchouli:spotlight","item":"endrem:evil_eye","text":"From the Night Lich.","link_recipe":true,"anchor":"evil_eye"},{"type":"patchouli:spotlight","item":"endrem:exotic_eye","text":"From the Sandworm.","link_recipe":true,"anchor":"exotic_eye"},{"type":"patchouli:spotlight","item":"endrem:old_eye","text":"From the Ancient Remnant.","link_recipe":true,"anchor":"old_eye"},{"type":"patchouli:spotlight","item":"endrem:guardian_eye","text":"From the Leviathan.","link_recipe":true,"anchor":"guardian_eye"},{"type":"patchouli:spotlight","item":"endrem:nether_eye","text":"From the Netherite Monstrosity.","link_recipe":true,"anchor":"nether_eye"}],"extra_recipe_mappings":{"endrem:magical_eye":0,"endrem:evil_eye":0,"endrem:exotic_eye":0,"endrem:old_eye":0,"endrem:guardian_eye":0,"endrem:nether_eye":0}},"en_us/entries/end/promax.json":{"name":"Wearing the Eyes","icon":"endrem:evil_eye","category":"patchouli:end","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Each eye can also be worn as a $(l)Curio$(), and each has a power of its own. The $(l:end/eyes2#evil_eye)Evil Eye$(/l) turns aside nearly all magic. The $(l:end/eyes2#exotic_eye)Exotic Eye$(/l) makes you a little better at everything.$(br2)Spare eyes are worth keeping."}]},"en_us/entries/magic/ars.json":{"name":"Ars Nouveau","icon":"ars_nouveau:novice_spell_book","category":"patchouli:magic","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Ars Nouveau lets you write your own spells from $(l)glyphs$(): a form, then effects, then augments.$(br2)$(li)The $(l:magic/ars#worn_notebook)Worn Notebook$(/l) is where it starts. You'll find its recipe at the end of this entry."},{"type":"patchouli:text","text":"$(li)$(l)Source$() is its power. Sourcelinks gather it and a $(l:magic/ars#source_jar)Source Jar$(/l) holds it.$(li)An $(l:magic/ars#imbuement_chamber)Imbuement Chamber$(/l) steeps items in Source.$(li)Spells are written in a $(l:magic/ars#novice_spell_book)Novice Spell Book$(/l). New glyphs are crafted at a Scribe's Table.$(br2)Look for the bright archwood forests."},{"type":"patchouli:crafting","recipe":"ars_nouveau:imbuement_chamber","anchor":"imbuement_chamber"},{"type":"patchouli:spotlight","item":"ars_nouveau:source_jar","text":"Stores Source for nearby machines.","link_recipe":true,"anchor":"source_jar"},{"type":"patchouli:crafting","recipe":"ars_nouveau:novice_spell_book","anchor":"novice_spell_book"},{"type":"patchouli:crafting","recipe":"ars_nouveau:worn_notebook","title":"Further Reading","text":"The $(l)Worn Notebook$() goes deeper.","anchor":"worn_notebook"}],"extra_recipe_mappings":{"ars_nouveau:worn_notebook":0,"ars_nouveau:imbuement_chamber":0,"ars_nouveau:source_jar":0,"ars_nouveau:novice_spell_book":0,"ars_nouveau:source_gem":0,"ars_nouveau:scribes_table":0,"ars_nouveau:archwood_planks":0}},"en_us/entries/magic/ars2.json":{"name":"Two Schools","icon":"irons_spellbooks:arcane_essence","category":"patchouli:magic","sortnum":5,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The two schools of magic lean on each other. A mage who ignores one will stall in the other.$(br2)$(li)Iron's $(l:magic/irons#ars_bond_inscription_table)Inscription Table$(/l) is bound with a Worn Notebook, and its $(l:magic/irons2#ars_bond_scroll_forge)Scroll Forge$(/l) is built around Source."},{"type":"patchouli:text","text":"$(li)Amethyst steeped in Source, with lapis on a pedestal beside it, becomes $(l:magic/ars2#arcane_essence)Arcane Essence$(/l).$(li)Ars essences can etch Iron's runes.$(li)Ars's greater spell books ask for Iron's essence and ingots."},{"type":"patchouli:spotlight","item":"irons_spellbooks:arcane_essence","text":"","link_recipe":true,"anchor":"arcane_essence"},{"type":"patchouli:crafting","recipe":"kubejs:ars_bond/fire_rune","recipe2":"kubejs:ars_bond/ice_rune","anchor":"ars_bond_fire_rune"},{"type":"patchouli:crafting","recipe":"ars_nouveau:apprentice_spell_book_upgrade","recipe2":"ars_nouveau:archmage_spell_book_upgrade","anchor":"apprentice_spell_book_upgrade"},{"type":"patchouli:crafting","recipe":"ars_nouveau:worn_notebook","title":"Further Reading","text":"The $(l)Worn Notebook$() goes deeper.","anchor":"worn_notebook"}],"extra_recipe_mappings":{"ars_nouveau:fire_essence":0,"ars_nouveau:apprentice_spell_book":0,"ars_nouveau:archmage_spell_book":0}},"en_us/entries/magic/catacombs.json":{"name":"The Catacombs","icon":"irons_spellbooks:wayward_compass","category":"patchouli:magic","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Beneath the world lie the Catacombs, and on a throne at their heart sits the $(l)Dead King$().$(br2)A $(l:magic/catacombs#wayward_compass)Wayward Compass$(/l) points the way. His death leaves a Bone Key for the vaults below."},{"type":"patchouli:crafting","recipe":"irons_spellbooks:wayward_compass","anchor":"wayward_compass"},{"type":"patchouli:crafting","recipe":"irons_spellbooks:patchouli_book","title":"Further Reading","text":"The $(l)Iron's Spells Guide$() goes deeper.","anchor":"patchouli_book"}],"extra_recipe_mappings":{"irons_spellbooks:wayward_compass":0}},"en_us/entries/magic/forbidden.json":{"name":"Forbidden Rituals","icon":"forbidden_arcanus:arcane_crystal","category":"patchouli:magic","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Forbidden & Arcanus is ritual magic, centred on the $(l:magic/forbidden#hephaestus_forge)Hephaestus Forge$(/l). Pedestals hold the offering, and the forge burns four essences: $(l)aureal$(), $(l)souls$(), $(l)blood$() and $(l)experience$()."},{"type":"patchouli:text","text":"Strike it with a $(l:magic/forbidden#wooden_blacksmith_gavel)Blacksmith Gavel$(/l) to begin. The forge grows stronger as you upgrade it."},{"type":"patchouli:spotlight","item":"forbidden_arcanus:hephaestus_forge","text":"","link_recipe":true,"anchor":"hephaestus_forge"},{"type":"patchouli:spotlight","item":"forbidden_arcanus:wooden_blacksmith_gavel,forbidden_arcanus:stone_blacksmith_gavel,forbidden_arcanus:golden_blacksmith_gavel,forbidden_arcanus:iron_blacksmith_gavel,forbidden_arcanus:diamond_blacksmith_gavel,forbidden_arcanus:netherite_blacksmith_gavel,forbidden_arcanus:reinforced_deorum_blacksmith_gavel","text":"","link_recipe":true,"title":"Blacksmith Gavel","anchor":"wooden_blacksmith_gavel"},{"type":"patchouli:spotlight","item":"forbidden_arcanus:arcane_crystal","text":"","link_recipe":true,"anchor":"arcane_crystal"},{"type":"patchouli:spotlight","item":"forbidden_arcanus:deorum_ingot","text":"A golden metal used in a lot of the mod.","link_recipe":true,"anchor":"deorum_ingot"}],"extra_recipe_mappings":{"forbidden_arcanus:arcane_crystal":0,"forbidden_arcanus:deorum_ingot":0,"forbidden_arcanus:hephaestus_forge":0}},"en_us/entries/magic/forbidden2.json":{"name":"Forbidden Tools","icon":"forbidden_arcanus:dark_rune","category":"patchouli:magic","sortnum":5,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l:magic/forbidden2#arcane_crystal_obelisk)Arcane Crystal Obelisk$(/l): gathers aureal for a nearby forge on its own.$(li)$(l:magic/forbidden2#quantum_catcher)Quantum Catcher$(/l): carries a living mob in your pocket.$(li)$(l:magic/forbidden#deorum_ingot)Deorum$(/l) and $(l:magic/forbidden2#edelwood_log)Edelwood$(/l): the mod's finest materials."},{"type":"patchouli:text","text":"Every ritual is listed in JEI."},{"type":"patchouli:spotlight","item":"forbidden_arcanus:arcane_crystal_obelisk","text":"","link_recipe":true,"anchor":"arcane_crystal_obelisk"},{"type":"patchouli:spotlight","item":"forbidden_arcanus:quantum_catcher","text":"","link_recipe":true,"anchor":"quantum_catcher"},{"type":"patchouli:spotlight","item":"forbidden_arcanus:edelwood_log","text":"","link_recipe":true,"anchor":"edelwood_log"}]},"en_us/entries/magic/hexerei.json":{"name":"Hexerei","icon":"hexerei:mixing_cauldron","category":"patchouli:magic","sortnum":6,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Hexerei is the quieter craft: herbs, candles, cauldrons and brooms.$(br2)Grow and dry herbs like $(l:magic/hexerei#sage_seed)Sage$(/l) and keep them in $(l:magic/hexerei#herb_jar)Herb Jars$(/l). Most of the work happens in the $(l:magic/hexerei#mixing_cauldron)Mixing Cauldron$(/l). The $(l:magic/hexerei#book_of_shadows)Book of Shadows$(/l) holds the rest."},{"type":"patchouli:text","text":"A $(l:magic/hexerei#willow_broom)Broom$(/l) will fly once it has a brush. Crows can be won over.$(br2)Swamp witches live in proper houses now. Some live in whole villages."},{"type":"patchouli:spotlight","item":"hexerei:sage_seed","text":"","link_recipe":true,"anchor":"sage_seed"},{"type":"patchouli:spotlight","item":"hexerei:herb_jar","text":"","link_recipe":true,"anchor":"herb_jar"},{"type":"patchouli:spotlight","item":"hexerei:mixing_cauldron","text":"","link_recipe":true,"anchor":"mixing_cauldron"},{"type":"patchouli:spotlight","item":"hexerei:book_of_shadows","text":"","link_recipe":true,"anchor":"book_of_shadows"},{"type":"patchouli:spotlight","item":"hexerei:willow_broom","text":"One of several brooms.","link_recipe":true,"anchor":"willow_broom"},{"type":"patchouli:crafting","recipe":"kubejs:guide_books/book_of_shadows","title":"Further Reading","text":"The $(l)Book of Shadows$() goes deeper.","anchor":"guide_books_book_of_shadows"}],"extra_recipe_mappings":{"hexerei:mixing_cauldron":0,"hexerei:herb_jar":0,"hexerei:willow_broom":0,"hexerei:book_of_shadows":0}},"en_us/entries/magic/irons.json":{"name":"Iron's Spells","icon":"irons_spellbooks:arcane_essence","category":"patchouli:magic","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Spells draw on your $(l)mana$(). A $(l:magic/irons2#ars_bond_scroll_forge)Scroll$(/l) holds a single spell: cast it once, or bind it into a spellbook at an $(l:magic/irons#ars_bond_inscription_table)Inscription Table$(/l) and keep it.$(br2)Spells come in levels and rarities, across nine schools from fire to eldritch."},{"type":"patchouli:text","text":"$(l:magic/irons#mithril_ore)Mithril$(/l) lies deep in the deepslate and needs a netherite pickaxe. Arcane Essence comes from magic mobs, old loot, and Ars Nouveau's Imbuement Chamber."},{"type":"patchouli:crafting","recipe":"kubejs:ars_bond/inscription_table","anchor":"ars_bond_inscription_table"},{"type":"patchouli:spotlight","item":"irons_spellbooks:mithril_ore","text":"Below y -38. Needs a netherite pickaxe. Blast the raw mithril into scrap; four scraps make an ingot.","link_recipe":true,"anchor":"mithril_ore"},{"type":"patchouli:crafting","recipe":"irons_spellbooks:patchouli_book","title":"Further Reading","text":"The $(l)Iron's Spells Guide$() goes deeper.","anchor":"patchouli_book"}],"extra_recipe_mappings":{"irons_spellbooks:arcane_essence":0,"irons_spellbooks:inscription_table":0,"irons_spellbooks:mithril_ore":0,"irons_spellbooks:mithril_ingot":0,"irons_spellbooks:arcane_ingot":0}},"en_us/entries/magic/irons2.json":{"name":"Spellcrafting","icon":"irons_spellbooks:scroll_forge","category":"patchouli:magic","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l:magic/irons2#ars_bond_scroll_forge)Scroll Forge$(/l): ink, paper and a focus make new scrolls. Better ink, rarer spells. Its heart is a Source Gem Block.$(li)$(l:magic/irons2#ars_bond_scroll_forge)Alchemist Cauldron$(/l): boils scrolls back down to ink, and brews."},{"type":"patchouli:text","text":"$(li)$(l:magic/irons2#arcane_anvil)Arcane Anvil$(/l): merges scrolls, imbues weapons, and sets an $(l:magic/irons2#arcane_anvil)Upgrade Orb$(/l) into armor."},{"type":"patchouli:crafting","recipe":"kubejs:ars_bond/scroll_forge","recipe2":"irons_spellbooks:alchemist_cauldron","anchor":"ars_bond_scroll_forge"},{"type":"patchouli:crafting","recipe":"irons_spellbooks:arcane_anvil","recipe2":"irons_spellbooks:upgrade_orb","anchor":"arcane_anvil"},{"type":"patchouli:crafting","recipe":"irons_spellbooks:patchouli_book","title":"Further Reading","text":"The $(l)Iron's Spells Guide$() goes deeper.","anchor":"patchouli_book"}],"extra_recipe_mappings":{"irons_spellbooks:scroll_forge":0,"irons_spellbooks:alchemist_cauldron":0,"irons_spellbooks:arcane_anvil":0,"irons_spellbooks:upgrade_orb":0,"irons_spellbooks:common_ink":0}},"en_us/entries/magic/irons3.json":{"name":"Magic Add-ons","icon":"irons_spellbooks:blank_rune","category":"patchouli:magic","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Iron's magic runs deeper than its own book: $(l)T.O Magic 'n Extras$(), dragon spells from $(l)Ice and Fire: Spellbooks$(), boss magic from $(l)Cataclysm: Spellbooks$(), and skill trees that grow as you cast."},{"type":"patchouli:text","text":"Wizard towers and the Catacombs are where scrolls collect."},{"type":"patchouli:crafting","recipe":"irons_spellbooks:patchouli_book","title":"Further Reading","text":"The $(l)Iron's Spells Guide$() goes deeper.","anchor":"patchouli_book"}]},"en_us/entries/magic/mystical.json":{"name":"Mystical Farming","icon":"mysticalagriculture:infusion_altar","category":"patchouli:magic","sortnum":7,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Mystical Agriculture grows resources like crops. Here, every tier has to be earned elsewhere in the world first."},{"type":"patchouli:text","text":"Seeds are made on an $(l:magic/mystical#mystical_infusion_altar)Infusion Altar$(/l) ringed by eight $(l:magic/mystical#mystical_infusion_altar)Pedestals$(/l). Every resource seed starts as a $(l:magic/mystical#mystical_prosperity_seed_base)Prosperity Seed Base$(/l), and every base needs a mandrake root. Crops only drop a second seed on Essence Farmland, more often on their own tier's. An $(l:magic/mystical#mystical_prosperity_seed_base)Infusion Crystal$(/l) wears out."},{"type":"patchouli:crafting","recipe":"kubejs:mystical/infusion_altar","recipe2":"kubejs:mystical/infusion_pedestal","anchor":"mystical_infusion_altar"},{"type":"patchouli:spotlight","item":"mysticalagriculture:wand","text":"Starts an infusion.","link_recipe":true,"anchor":"wand"},{"type":"patchouli:crafting","recipe":"kubejs:mystical/prosperity_seed_base","recipe2":"kubejs:mystical/infusion_crystal","anchor":"mystical_prosperity_seed_base"}],"extra_recipe_mappings":{"mysticalagriculture:infusion_altar":0,"mysticalagriculture:infusion_pedestal":0,"mysticalagriculture:prosperity_seed_base":0,"mysticalagriculture:infusion_crystal":0}},"en_us/entries/magic/mystical2.json":{"name":"Climbing the Tiers","icon":"mysticalagriculture:supremium_essence","category":"patchouli:magic","sortnum":8,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Higher essence isn't crafted here. It's brewed in a $(l:crafting/create#crafting_kinetics_mechanical_press)Create mixer$(/l): four of one tier around an $(l:magic/mystical#mystical_prosperity_seed_base)Infusion Crystal$(/l) make four of the next. Each mix spends one of the crystal's 500 uses, and the mixer hands the crystal back with the essence."},{"type":"patchouli:text","text":"Supremium and Insanium need the $(l:magic/mystical2#mystical_machine_frame)Master Infusion Crystal$(/l), which never wears out. It takes Imperium and a Nether Star. Imperium and Supremium need a heated mixer; Insanium needs a superheated one."},{"type":"patchouli:text","text":"The $(l:magic/mystical2#mystical_machine_frame)Machine Frame$(/l) is Create brass. The $(l:magic/mystical2#mystical_awakening_altar)Awakening Altar$(/l) needs Ignitium.$(br2)Insanium ends the climb."},{"type":"patchouli:text","text":"Two $(l:magic/mystical2#insanium_gear_insanium_chestplate)Insanium Ingots$(/l) and two $(l:magic/mystical2#insanium_gear_insanium_chestplate)Insanium Gemstones$(/l) around a piece of Awakened Supremium gear make its $(l)Mystical Adaptations$() Insanium version, the strongest armor and tools in the mod."},{"type":"patchouli:text","text":"The piece keeps its enchantments, gems, quality, augments and name. Kill the Wither or the Ender Dragon with an Insanium weapon and it drops Insanium Essence."},{"type":"patchouli:text","text":"Every tier also makes an $(l:magic/mystical2#mystical_staff_inferium_staff)Essence Staff$(/l). Here they are spell staves: they hit hard, raise spell power and mana regeneration, and hold imbued spells, one at Inferium and four at Insanium. Put a scroll on one at an Arcane Anvil to imbue it; each scroll fills the next slot."},{"type":"patchouli:spotlight","item":"mysticalagriculture:inferium_essence","text":"Grown, not mixed: Inferium crops drop it. Every tier above starts here.","link_recipe":true,"anchor":"inferium_essence"},{"type":"patchouli:fairytale_mixer","title":"Prudentium Essence","item":"mysticalagriculture:prudentium_essence","lower":"mysticalagriculture:inferium_essence","crystal":"mysticalagriculture:infusion_crystal","out":"mysticalagriculture:prudentium_essence#4","heat":"minecraft:air","text":"Four Inferium round an Infusion Crystal, in any mixer. One crystal use per four essence.","anchor":"prudentium_essence"},{"type":"patchouli:fairytale_mixer","title":"Tertium Essence","item":"mysticalagriculture:tertium_essence","lower":"mysticalagriculture:prudentium_essence","crystal":"mysticalagriculture:infusion_crystal","out":"mysticalagriculture:tertium_essence#4","heat":"minecraft:air","text":"Four Prudentium round an Infusion Crystal, in any mixer. One crystal use per four essence.","anchor":"tertium_essence"},{"type":"patchouli:fairytale_mixer","title":"Imperium Essence","item":"mysticalagriculture:imperium_essence","lower":"mysticalagriculture:tertium_essence","crystal":"mysticalagriculture:infusion_crystal","out":"mysticalagriculture:imperium_essence#4","heat":"create:blaze_burner","text":"Four Tertium round an Infusion Crystal, heated. One crystal use per four essence.","anchor":"imperium_essence"},{"type":"patchouli:fairytale_mixer","title":"Supremium Essence","item":"mysticalagriculture:supremium_essence","lower":"mysticalagriculture:imperium_essence","crystal":"mysticalagriculture:master_infusion_crystal","out":"mysticalagriculture:supremium_essence#4","heat":"create:blaze_burner","text":"Four Imperium round the Master Crystal, heated. It never wears out.","anchor":"supremium_essence"},{"type":"patchouli:fairytale_mixer","title":"Insanium Essence","item":"mysticalagradditions:insanium_essence","lower":"mysticalagriculture:supremium_essence","crystal":"mysticalagriculture:master_infusion_crystal","out":"mysticalagradditions:insanium_essence#4","heat":"create:blaze_cake","text":"Four Supremium round the Master Crystal, superheated with a Blaze Cake.","anchor":"insanium_essence"},{"type":"patchouli:crafting","recipe":"kubejs:mystical/machine_frame","recipe2":"kubejs:mystical/master_infusion_crystal","anchor":"mystical_machine_frame"},{"type":"patchouli:crafting","recipe":"kubejs:mystical/awakening_altar","anchor":"mystical_awakening_altar"},{"type":"patchouli:crafting","recipe":"kubejs:insanium_gear/insanium_chestplate","recipe2":"kubejs:insanium_gear/insanium_sword","title":"Insanium Gear","anchor":"insanium_gear_insanium_chestplate"},{"type":"patchouli:crafting","recipe":"kubejs:mystical/staff/inferium_staff","recipe2":"kubejs:mystical/staff/prudentium_staff","title":"Essence Staffs","anchor":"mystical_staff_inferium_staff"}],"extra_recipe_mappings":{"mysticalagriculture:inferium_essence":0,"mysticalagriculture:prudentium_essence":0,"mysticalagriculture:tertium_essence":0,"mysticalagriculture:imperium_essence":0,"mysticalagriculture:supremium_essence":0,"mysticalagradditions:insanium_essence":0,"mysticalagriculture:machine_frame":0,"mysticalagradditions:insanium_ingot":0,"mysticalagradditions:insanium_gemstone":0}},"en_us/entries/world/about.json":{"name":"Using This Book","icon":"minecraft:book","category":"patchouli:world","sortnum":-1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Notes on how this world works, gathered as I went. Not everything is written down. Some things you'll have to find out the hard way.$(br2)$(li)Hover anything pictured and press $(l)R$() for its recipe, $(l)U$() for its uses."},{"type":"patchouli:text","text":"$(li)Lost the book? A book and a compass will bind another."},{"type":"patchouli:crafting","recipe":"kubejs:adventure_book","anchor":"adventure_book"}]},"en_us/entries/world/backport.json":{"name":"Newer Features","icon":"minecraft:spyglass","category":"patchouli:world","sortnum":6,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"A few things from newer Minecraft have found their way here: the Pale Garden and the Creaking, armadillos and wolf armor, dyed bundles, happy ghasts and sulfur caves.$(br2)Mobs move with $(l)Fresh Animations$()."}]},"en_us/entries/world/death.json":{"name":"When You Die","icon":"minecraft:skeleton_skull","category":"patchouli:world","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"When you die, a $(l)corpse$() stays where you fell with everything you carried. Get back to it before something else does."}]},"en_us/entries/world/difficulty.json":{"name":"A Harder World","icon":"minecraft:netherite_sword","category":"patchouli:world","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The world grows harder in three stages. $(l)Expert$() begins the first time anyone crosses into another dimension. $(l)Master$() begins when the Ender Dragon falls."},{"type":"patchouli:text","text":"Some mobs now travel in packs behind a leader. Kill enough undead and an $(l)Undead Army$() comes for you, with Born in Chaos horrors in its ranks.$(br2)Think twice before that first trip to the Nether."},{"type":"patchouli:text","text":"Gear forged here is a little stronger than you may be used to, with harder-hitting blades and tougher armor. You'll need it."}]},"en_us/entries/world/food_health.json":{"name":"A Varied Diet","icon":"farmersdelight:beef_stew","category":"patchouli:world","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Eat the same meal day after day and it stops doing much for you. Each repeat fills you a little less, down to almost nothing."},{"type":"patchouli:text","text":"Keep a few dishes in rotation and you'll hardly notice. A food's tooltip shows how tired of it you are. The $(l:world/food_health#food_history_book)Food History Book$(/l) remembers what you've eaten, and a $(l:world/food_health#wicker_basket)Wicker Basket$(/l) feeds you from whatever you've packed.$(br2)Golden apples, kelp, honey and chorus fruit never grow stale."},{"type":"patchouli:spotlight","item":"solclassic:wicker_basket","text":"Holds 9 stacks of food. Right-click to eat the best one; sneak + right-click to open.","link_recipe":true,"anchor":"wicker_basket"},{"type":"patchouli:spotlight","item":"solclassic:food_history_book","text":"Shows every food you have eaten.","link_recipe":true,"anchor":"food_history_book"}]},"en_us/entries/world/seasons.json":{"name":"Seasons","icon":"sereneseasons:calendar","category":"patchouli:world","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The year turns through four seasons, and each crop has its own. Out of season it barely grows. A seed's tooltip lists its seasons.$(br2)Deep underground, below y 48, the seasons don't reach your crops."},{"type":"patchouli:text","text":"Winter brings snow to places that never see it. A $(l:world/seasons#calendar)Calendar$(/l) tells you how long until the next turn."},{"type":"patchouli:spotlight","item":"sereneseasons:calendar","text":"Shows the season and how far into it you are.","link_recipe":true,"anchor":"calendar"}],"extra_recipe_mappings":{"sereneseasons:calendar":0}},"en_us/entries/world/skills.json":{"name":"Skill Trees","icon":"irons_spellbooks:arcane_essence","category":"patchouli:world","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Casting spells earns experience in four magic skill trees. Open them with the skills key and spend points to strengthen your magic.$(br2)Resetting a tree costs nothing, so experiment."}]},"en_us/entries/notes/night.json":{"name":"What's Left","icon":"minecraft:paper","category":"patchouli:notes","sortnum":1,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"You'll have noticed the pages. Most of them are gone.$(br2)I didn't do that. Whatever took the Crown came back for my notes. It knew I'd been following it, and it tore out every page that said where to go next."},{"type":"patchouli:text","text":"Then it handed them out, one to each of the things out there big enough to keep them.$(br2)So that's the only way forward now. Find them, beat them, and take back what's mine."},{"type":"patchouli:text","text":"The first one is the easiest. There's an iron giant asleep in a chamber under the hills. Only its back can be hurt, and only right after it swings.$(br2)$(o)The miners swear the Ferrous Wroughtnaut keeps the Lost Eye, asleep in an iron chamber deep under the Overworld.$()"}],"advancement":"kubejs:fairytale/night"},"en_us/entries/notes/p01.json":{"name":"Under the Hills","icon":"minecraft:paper","category":"patchouli:notes","sortnum":2,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"You got it back. Good. That's one.$(br2)There's a beast up in the snowfields bigger than a house, asleep with something clutched in its hand. Taking it wakes it up. Don't reach for it unless you're ready to fight."},{"type":"patchouli:text","text":"$(o)Trappers say the Frostmaw holds the Cold Eye. It sleeps out in the open snow.$()"}],"advancement":"kubejs:fairytale/p01"},"en_us/entries/notes/p02.json":{"name":"The Snowfields","icon":"minecraft:paper","category":"patchouli:notes","sortnum":3,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"Sorry about the writing. My hands were cold."},{"type":"patchouli:text","text":"Somewhere warmer, where the grass goes yellow and the trees are flat on top, there's a tribe in bird masks. Their king sits on a throne in the middle of a grove. He won't stay sitting for long once you walk in."},{"type":"patchouli:text","text":"$(o)Anyone who has crossed the savanna has heard of Umvuthi, the Sunbird, and the Rogue Eye he keeps on his throne.$()"}],"advancement":"kubejs:fairytale/p02"},"en_us/entries/notes/p03.json":{"name":"The Grove","icon":"minecraft:paper","category":"patchouli:notes","sortnum":4,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"The next one is the strangest thing in this book."},{"type":"patchouli:text","text":"Somebody left a ring of candles around a rotten pumpkin, out in the middle of nowhere. Break the pumpkin and a rider comes out of it. Sir Pumpkinhead, people call him. Kill the horse first if you can."},{"type":"patchouli:text","text":"$(o)Sir Pumpkinhead rides with the Witch Eye. His candle shrines turn up all over the Overworld, and they're easiest to spot at night.$()"}],"advancement":"kubejs:fairytale/p03"},"en_us/entries/notes/p04.json":{"name":"The Pumpkin Rider","icon":"minecraft:paper","category":"patchouli:notes","sortnum":5,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"Under the ground there are catacombs, old tombs from before my time. The dead down there don't stay down.$(br2)The Dead King sits on a throne at the heart of them. I went down once. I came back up a lot faster than I went in."},{"type":"patchouli:text","text":"$(o)Gravediggers mutter that the Dead King guards the Undead Eye, deep in the Catacombs. A Wayward Compass knows the way.$()"}],"advancement":"kubejs:fairytale/p04"},"en_us/entries/notes/p05.json":{"name":"The Catacombs","icon":"minecraft:paper","category":"patchouli:notes","sortnum":6,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"Go out past the last of the land, to where the deep sea freezes into a maze."},{"type":"patchouli:text","text":"There are pirate ships stuck in the ice. Their captain carries a horn made from a shell. Blow it near open water inside the maze and something answers. Her name was Cornelia, once. She has a key, and a page."},{"type":"patchouli:text","text":"$(o)Sailors won't say Captain Cornelia's name, but they'll tell you she took the Black Eye down with her. Her ghost haunts the Ice Maze, over the deep frozen ocean.$()"}],"advancement":"kubejs:fairytale/p05"},"en_us/entries/notes/p06.json":{"name":"The Frozen Sea","icon":"minecraft:paper","category":"patchouli:notes","sortnum":7,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"I only know this one secondhand, so bear with me."},{"type":"patchouli:text","text":"There's a forest where it's always dusk. You get there through a small pool ringed with flowers, if you throw a diamond in. Deep inside there's a lich at the top of a tower. The tower won't open until you've beaten the great snake first."},{"type":"patchouli:text","text":"$(o)The Twilight Lich hoards the Magical Eye at the top of his tower in the Twilight Forest. Beat the Naga first, or the door stays shut.$()"}],"advancement":"kubejs:fairytale/p06"},"en_us/entries/notes/p07.json":{"name":"The Dusk Forest","icon":"minecraft:paper","category":"patchouli:notes","sortnum":8,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"There's another lich, and he's nothing to do with that forest.$(br2)He lives up in the cold, in a tower of his own. The undead out here sometimes drop a little star. Throw it and it flies toward the tower. Put four on the altars inside and he'll come."},{"type":"patchouli:text","text":"$(o)Whispers say the Night Lich keeps the Evil Eye, in his tower out in the cold biomes.$()"}],"advancement":"kubejs:fairytale/p07"},"en_us/entries/notes/p08.json":{"name":"The Cold Tower","icon":"minecraft:paper","category":"patchouli:notes","sortnum":9,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"The desert has a worm in it.$(br2)It moves under the sand and comes up when it's found you. Wait for it to surface, then hit it."},{"type":"patchouli:text","text":"$(o)Caravan drivers say the Sandworm swallowed the Exotic Eye. It hunts beneath the desert.$()"}],"advancement":"kubejs:fairytale/p08"},"en_us/entries/notes/p09.json":{"name":"The Worm","icon":"minecraft:paper","category":"patchouli:notes","sortnum":10,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"There's a pyramid in the desert that isn't like the others. The locals won't go near it.$(br2)Whatever is inside won't wake on its own. It wakes for one thing: the Necklace of the Desert. I'd rather it stayed asleep, but you need what it's holding."},{"type":"patchouli:text","text":"$(o)The Ancient Remnant sleeps on the Old Eye, inside the Cursed Pyramid out in the desert.$()"}],"advancement":"kubejs:fairytale/p09"},"en_us/entries/notes/p10.json":{"name":"Cursed Pyramid","icon":"minecraft:paper","category":"patchouli:notes","sortnum":11,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"There's a city under the sea. Whole streets of it, sunk.$(br2)The Leviathan lives there. Bring something to breathe with, and don't fight it in open water if you can help it."},{"type":"patchouli:text","text":"$(o)The few divers who came back talk of the Leviathan and the Guardian Eye it carries, down in the Sunken City under the ocean.$()"}],"advancement":"kubejs:fairytale/p10"},"en_us/entries/notes/p11.json":{"name":"The Sunken City","icon":"minecraft:paper","category":"patchouli:notes","sortnum":12,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"The last eye is in the Nether.$(br2)There's a forge down there that was built for souls. Something made of netherite still works it. It doesn't like visitors."},{"type":"patchouli:text","text":"$(o)The Netherite Monstrosity still works the Soul Forge, with the Nether Eye close at hand. Somewhere in the Nether.$()"}],"advancement":"kubejs:fairytale/p11"},"en_us/entries/notes/p12.json":{"name":"Twelve","icon":"minecraft:paper","category":"patchouli:notes","sortnum":13,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"That should be twelve. Enough to open the way, if you find the stronghold."},{"type":"patchouli:text","text":"But you need to know something first. The Crown wasn't just stolen. It was broken. The eyes were its power, and the Crown itself is in four pieces, kept by the four worst things I know of. Go through that portal now and there's nothing waiting for you but a dragon."},{"type":"patchouli:text","text":"The first piece: there's a black fortress hidden in the Nether, and a knight lives in it. The Underworld Knight, they call him."},{"type":"patchouli:text","text":"$(o)Every scout who went after the Band of the Crown came back saying the same thing: the Underworld Knight has it, in his black fortress in the Nether.$()"}],"advancement":"kubejs:fairytale/p12"},"en_us/entries/notes/p13.json":{"name":"The Black Fortress","icon":"minecraft:paper","category":"patchouli:notes","sortnum":14,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"That's the band. The rest was built on it.$(br2)The jewel is somewhere much worse. At the very bottom of the world there are caves hardly anyone finds, and something grows down there. Void lilies point the way."},{"type":"patchouli:text","text":"$(o)The Jewel of the Crown is tangled in the Void Blossom, in rare caves at the very bottom of the Overworld.$()"}],"advancement":"kubejs:fairytale/p13"},"en_us/entries/notes/p14.json":{"name":"Bottom of the World","icon":"minecraft:paper","category":"patchouli:notes","sortnum":15,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"The jewel. I'd forgotten how it catches the light.$(br2)The next piece is inside the Wither. Three skulls and four blocks of soul sand. I never had the nerve to build one. If you do, do it far from home."},{"type":"patchouli:text","text":"$(o)Nobody whispers about this one. Nobody's fool enough to build it. The Crest of the Crown is inside the Wither, wherever you dare to raise it.$()"}],"advancement":"kubejs:fairytale/p14"},"en_us/entries/notes/p15.json":{"name":"The Wither","icon":"minecraft:paper","category":"patchouli:notes","sortnum":16,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"That's the crest. The King's mark.$(br2)The star it dropped isn't just a trophy. There's a machine in a factory underground that hasn't moved in a hundred years, and a Nether Star is what wakes it. It has the last piece. Be quick."},{"type":"patchouli:text","text":"$(o)The Setting of the Crown is with the Harbinger, switched off in a factory buried in the Overworld's caves.$()"}],"advancement":"kubejs:fairytale/p15"},"en_us/entries/notes/p16.json":{"name":"The Machine","icon":"minecraft:paper","category":"patchouli:notes","sortnum":17,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"That's all four.$(br2)They won't hold together on their own. They need something to bind them, a heart that's never gone cold, and there's only one of those I know of. It's in the dragon."},{"type":"patchouli:text","text":"Put the eyes in the frame and go through. Then bring every piece together and make it whole.$(br2)$(o)The last thing you need is still beating inside the Ender Dragon, in the End.$()"}],"advancement":"kubejs:fairytale/p16"},"en_us/entries/notes/p17.json":{"name":"Bring It Home","icon":"kubejs:kings_crown","category":"patchouli:notes","sortnum":18,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"The last page was blank when you found this book. It isn't now.$(br2)In different ink, in a hand you don't recognise:$(br2)$(o)Thank you. The roads will be safe again. — A.$()"},{"type":"patchouli:crafting","recipe":"kubejs:kings_crown","anchor":"kings_crown"}],"advancement":"kubejs:fairytale/p17"},"en_us/entries/notes/start.json":{"name":"Apollo's Book","icon":"minecraft:writable_book","category":"patchouli:notes","sortnum":0,"read_by_default":false,"pages":[{"type":"patchouli:text","text":"This book belongs to Apollo Thorne, map-maker to the King.$(br2)If you found it on me, I'm likely dead, and I'm sorry you had to see that. If you found it somewhere else, then I lost it, which is almost worse."},{"type":"patchouli:text","text":"Either way, keep it. Most of what's in here is how to stay alive out there. The rest is what I know about the Crown."}]},"en_us/entries/food/addons.json":{"name":"Delight Add-ons","icon":"farmersdelight:ratatouille","category":"patchouli:food","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Nearly every creature and realm has dishes of its own: $(l)Alex's Delight$(), $(l)Nether's Delight$() and its $(l:food/addons#blackstone_stove)Blackstone Stove$(/l), $(l)Ender's Delight$(), $(l)Ocean's Delight$(), $(l)Ice and Fire Delight$(), $(l)Twilight's Flavors & Delight$(), and more."},{"type":"patchouli:text","text":"Go hungry for something new now and then."},{"type":"patchouli:spotlight","item":"nethersdelight:blackstone_stove","text":"A stove for Nether cooking.","link_recipe":true,"anchor":"blackstone_stove"}]},"en_us/entries/food/delight.json":{"name":"Farmer's Delight","icon":"farmersdelight:cooking_pot","category":"patchouli:food","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Most of the cooking here starts with Farmer's Delight."},{"type":"patchouli:text","text":"A knife and a $(l:food/delight#flint_knife)Cutting Board$(/l) prepare ingredients. The $(l:food/delight#cooking_pot)Cooking Pot$(/l) sits over heat for soups and stews, and the $(l:food/delight#skillet)Skillet$(/l) works on a stove. $(l:food/delight#rich_soil)Rich Soil$(/l) grows crops faster.$(br2)Big meals leave you $(l)Comforted$() and $(l)Nourished$()."},{"type":"patchouli:crafting","recipe":"farmersdelight:flint_knife","recipe2":"farmersdelight:cutting_board","anchor":"flint_knife"},{"type":"patchouli:crafting","recipe":"farmersdelight:cooking_pot","recipe2":"farmersdelight:stove","anchor":"cooking_pot"},{"type":"patchouli:crafting","recipe":"farmersdelight:skillet","anchor":"skillet"},{"type":"patchouli:spotlight","item":"farmersdelight:rich_soil","text":"Crops on it grow faster.","link_recipe":true,"anchor":"rich_soil"}],"extra_recipe_mappings":{"farmersdelight:cooking_pot":0,"farmersdelight:cutting_board":0,"farmersdelight:flint_knife":0,"farmersdelight:skillet":0,"farmersdelight:rich_soil":0}},"en_us/entries/food/fishing.json":{"name":"Aquaculture","icon":"minecraft:fishing_rod","category":"patchouli:food","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Aquaculture fills the water with fish that keep to their own biomes."},{"type":"patchouli:text","text":"Rods take a hook, bait, line and bobber, and the better metals last longer. A fillet knife turns a catch into something cookable. Fish long enough and the sea may give up a Neptune's Bounty.$(br2)$(l:food/tide)Tide$(/l) works alongside it. Use whichever rod you like."}]},"en_us/entries/food/tide.json":{"name":"Tide","icon":"tide:fishing_journal","category":"patchouli:food","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Tide brings new rods, more than a hundred new fish, and a $(l:food/tide#fishing_journal)Fishing Journal$(/l) that remembers every catch."},{"type":"patchouli:text","text":"Fish keep to their own waters, depths and weather. When one bites, a bar appears: click on the light zone and it's yours, on the dark zone and it's gone. Hooks and lines go on at the $(l:food/tide#angling_table)Angling Table$(/l), and $(l:food/tide#bait)Bait$(/l) goes in the rod."},{"type":"patchouli:text","text":"Tide's own rods, $(l:food/tide#crystal_fishing_rod)Crystal$(/l) among them, last longer than plain ones. Your $(l:food/fishing)Aquaculture$(/l) rods still work."},{"type":"patchouli:spotlight","item":"tide:fishing_journal","text":"Records every fish you catch.","link_recipe":true,"anchor":"fishing_journal"},{"type":"patchouli:spotlight","item":"tide:angling_table","text":"Fits gear onto Tide rods.","link_recipe":true,"anchor":"angling_table"},{"type":"patchouli:spotlight","item":"tide:bait","text":"","link_recipe":true,"anchor":"bait"},{"type":"patchouli:spotlight","item":"tide:crystal_fishing_rod","text":"","link_recipe":true,"anchor":"crystal_fishing_rod"},{"type":"patchouli:crafting","recipe":"kubejs:guide_books/fishing_journal","title":"Further Reading","text":"The $(l)Fishing Journal$() goes deeper.","anchor":"guide_books_fishing_journal"}],"extra_recipe_mappings":{"tide:fishing_journal":0,"tide:angling_table":0,"tide:crystal_fishing_rod":0,"tide:iron_fishing_rod":0,"tide:bait":0}},"en_us/entries/gear/apotheosis.json":{"name":"Apotheosis","icon":"apotheosis:gem","category":"patchouli:gear","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Apotheosis reaches into everything.$(br2)$(li)Gear drops with a rarity and $(l)affixes$().$(li)$(l)Gems$() go into sockets. Cut them at a $(l:gear/apotheosis#gem_cutting_table)Gem Cutting Table$(/l)."},{"type":"patchouli:text","text":"$(li)Salvage what you don't want and rework what you keep at the $(l:gear/apotheosis#augmenting_table)Augmenting Table$(/l).$(li)Bookshelves shape your enchantments in ways vanilla never did.$(br2)And some bosses walk the world wearing very good gear."},{"type":"patchouli:spotlight","item":"apotheosis:gem","text":"","link_recipe":true,"anchor":"gem"},{"type":"patchouli:spotlight","item":"apotheosis:gem_cutting_table","text":"","link_recipe":true,"anchor":"gem_cutting_table"},{"type":"patchouli:spotlight","item":"apotheosis:augmenting_table","text":"","link_recipe":true,"anchor":"augmenting_table"},{"type":"patchouli:crafting","recipe":"apotheosis:book","title":"Further Reading","text":"The $(l)Chronicle of Shadows$() goes deeper.","anchor":"book"}],"extra_recipe_mappings":{"apotheosis:gem":0,"apotheosis:gem_cutting_table":0,"apotheosis:augmenting_table":0,"apotheosis:library":0}},"en_us/entries/gear/armor.json":{"name":"Armor Mods","icon":"minecraft:netherite_chestplate","category":"patchouli:gear","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Advanced Netherite$(): netherite can be pushed further with iron, gold, emerald and diamond, each step with its own perk.$(li)$(l)Immersive Armors$(): sets with personalities of their own."},{"type":"patchouli:text","text":"$(li)$(l)Cosmetic Armor$(): wear one look over another's stats.$(br2)Most bosses leave armor behind too."}]},"en_us/entries/gear/quality.json":{"name":"Item Quality","icon":"minecraft:anvil","category":"patchouli:gear","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Gear often comes with a $(l)quality$() in its name, and it matters. A Rusted blade is a lesser thing than a Keen one, and won't last as long. Legendary weapons and Masterful armor are worth chasing."},{"type":"patchouli:text","text":"Don't like what you got? A $(l)Reforging Station$() will reroll it for the item's repair material, as many times as you can afford."}]},"en_us/entries/gear/souls.json":{"name":"Soulslike Weaponry","icon":"minecraft:netherite_sword","category":"patchouli:gear","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Mjolnir, the Leviathan Axe, the Moonlight Greatsword. Marium's Soulslike Weaponry forges legends from the remains of its bosses: the Draugr, the Accursed Lord, the Moonknight, the Chaos Monarch and others."},{"type":"patchouli:text","text":"JEI will tell you which boss each weapon needs."},{"type":"patchouli:spotlight","item":"soulsweapons:leviathan_axe","text":"","link_recipe":true,"anchor":"leviathan_axe"},{"type":"patchouli:spotlight","item":"soulsweapons:mjolnir","text":"","link_recipe":true,"anchor":"mjolnir"}]},"en_us/entries/gear/weapons.json":{"name":"Weapon Mods","icon":"minecraft:iron_axe","category":"patchouli:gear","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Spartan Weaponry$(): every kind of blade, polearm and throwing weapon, in every metal, dragonbone and dragonsteel included.$(li)$(l)Epic Knights$(): medieval armor, shields and arms."},{"type":"patchouli:text","text":"Weapon types differ a lot in reach, speed and damage. Read before you swing."}]},"en_us/entries/bosses/aquamirae.json":{"name":"Aquamirae","icon":"aquamirae:frozen_key","category":"patchouli:bosses","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Over the deep frozen ocean lies the $(l)Ice Maze$(), a graveyard of pirate ships."},{"type":"patchouli:text","text":"Take a Shell Horn from a pirate captain and blow it near open water to call up the $(l)Ghost of Captain Cornelia$(). Her $(l:bosses/aquamirae#frozen_key)Frozen Key$(/l) opens a chest in a shelter below.$(br2)The Maze Mother hunts near the anglerfish. The Shipbreaker can't be beaten. Run."},{"type":"patchouli:spotlight","item":"aquamirae:frozen_key","text":"Opens one Frozen Chest.","link_recipe":true,"anchor":"frozen_key"}],"extra_recipe_mappings":{"aquamirae:frozen_key":0}},"en_us/entries/bosses/bomd.json":{"name":"Mass Destruction","icon":"bosses_of_mass_destruction:soul_star","category":"patchouli:bosses","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Night Lich$(): in the cold. Undead drop $(l:bosses/bomd#soul_star)Soul Stars$(/l) that fly toward its tower. Four of them call it down.$(li)$(l)Nether Gauntlet$(): in a rare structure in the Nether."},{"type":"patchouli:text","text":"$(li)$(l)Void Blossom$(): at the very bottom of the world. Void lilies point the way.$(li)$(l)Obsidilith$(): in a rare structure out on the End islands."},{"type":"patchouli:spotlight","item":"bosses_of_mass_destruction:soul_star","text":"Throw it and follow it to the Night Lich's tower.","link_recipe":true,"anchor":"soul_star"}],"extra_recipe_mappings":{"bosses_of_mass_destruction:soul_star":0}},"en_us/entries/bosses/bossesrise.json":{"name":"Bosses'Rise","icon":"block_factorys_bosses:knight_sword","category":"patchouli:bosses","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The Underworld Knight, the Sandworm, the Yeti, the Infernal Dragon and the Kraken. Each keeps its own ground and fights like it means it.$(br2)Press $(l)Z$() to roll."},{"type":"patchouli:spotlight","item":"block_factorys_bosses:knight_sword","text":"","link_recipe":true,"anchor":"knight_sword"},{"type":"patchouli:spotlight","item":"block_factorys_bosses:sandworm_gauntlet","text":"","link_recipe":true,"anchor":"sandworm_gauntlet"}]},"en_us/entries/bosses/cataclysm.json":{"name":"Cataclysm","icon":"cataclysm:ignitium_ingot","category":"patchouli:bosses","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Cataclysm's bosses wait at the bottom of great dungeons in every dimension: the Netherite Monstrosity, the Ender Guardian, the Harbinger, the Ancient Remnant, the Leviathan, Scylla, Maledictus, and Ignis."},{"type":"patchouli:text","text":"Some sleep until you wake them. Craftable eyes point to their lairs."},{"type":"patchouli:spotlight","item":"cataclysm:ignitium_ingot","text":"From Ignis. Makes some of the best armor in the pack.","link_recipe":true,"anchor":"ignitium_ingot"},{"type":"patchouli:spotlight","item":"cataclysm:ancient_metal_ingot","text":"From the Ancient Remnant.","link_recipe":true,"anchor":"ancient_metal_ingot"}],"extra_recipe_mappings":{"cataclysm:ignitium_ingot":0,"cataclysm:ancient_metal_ingot":0}},"en_us/entries/bosses/chaosbosses.json":{"name":"Chaos Bosses","icon":"born_in_chaos_v1:bonescaller_staff","category":"patchouli:bosses","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Sir Pumpkinhead$(): break the evil pumpkin at the heart of his candle shrine. Near Halloween, he may come on his own.$(li)$(l)Lord Pumpkinhead$(): worse. Use a Transmuting Elixir on that same pumpkin."}]},"en_us/entries/bosses/knightquest.json":{"name":"Knight Quest","icon":"minecraft:iron_chestplate","category":"patchouli:bosses","sortnum":5,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Knight Quest brings more than thirty armor sets, each with a passive of its own, and new creatures to earn them from. Its boss is Netherman, the Architect of Chaos, a fight in three phases."}]},"en_us/entries/bosses/mowzie.json":{"name":"Mowzie's Mobs","icon":"mowziesmobs:wrought_axe","category":"patchouli:bosses","sortnum":7,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Ferrous Wroughtnaut$(): asleep in an iron chamber underground. Only its back can be hurt. It guards the $(l:bosses/mowzie#wrought_axe)Axe of a Thousand Metals$(/l)."},{"type":"patchouli:text","text":"$(li)$(l)Frostmaw$(): sleeping in the snow, holding an $(l:bosses/mowzie#ice_crystal)Ice Crystal$(/l). Taking the crystal is a mistake you'll only make once.$(li)$(l)Umvuthi$(): the Sunbird, on a throne in the savanna."},{"type":"patchouli:spotlight","item":"mowziesmobs:wrought_axe","text":"","link_recipe":true,"anchor":"wrought_axe"},{"type":"patchouli:spotlight","item":"mowziesmobs:ice_crystal","text":"","link_recipe":true,"anchor":"ice_crystal"}],"extra_recipe_mappings":{"mowziesmobs:wrought_axe":0,"mowziesmobs:ice_crystal":0}},"en_us/entries/bosses/others.json":{"name":"Other Bosses","icon":"twilightforest:lich_tower_miniature_structure","category":"patchouli:bosses","sortnum":6,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"The Twilight Forest's bosses, the Dead King, the Soulslike lords, the Wither and the Warden all have something you'll need. Some of them can be fought again."}]},"en_us/entries/trinkets/artifacts.json":{"name":"Artifacts","icon":"artifacts:cloud_in_a_bottle","category":"patchouli:trinkets","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Artifacts do one thing each, and do it well: double jumps, fire immunity, night vision, heavier fists.$(br2)They can't be crafted. Look in dungeon chests, underground camps, and the mouths of $(l)mimics$()."},{"type":"patchouli:spotlight","item":"artifacts:cloud_in_a_bottle","text":"Double jump.","link_recipe":true,"anchor":"cloud_in_a_bottle"},{"type":"patchouli:spotlight","item":"artifacts:running_shoes","text":"Faster running and step-up.","link_recipe":true,"anchor":"running_shoes"},{"type":"patchouli:spotlight","item":"artifacts:flame_pendant","text":"Sets attackers on fire.","link_recipe":true,"anchor":"flame_pendant"}],"extra_recipe_mappings":{"artifacts:cloud_in_a_bottle":0,"artifacts:running_shoes":0,"artifacts:flame_pendant":0,"artifacts:power_glove":0}},"en_us/entries/trinkets/curios.json":{"name":"Worn Items","icon":"minecraft:totem_of_undying","category":"patchouli:trinkets","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Rings, necklaces and belts go in your $(l)Curios$() slots, behind the button beside your character. End Remastered's eyes can be worn too."}]},"en_us/entries/trinkets/relics.json":{"name":"Relics","icon":"relics:magic_mirror","category":"patchouli:trinkets","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Relics turn up only in chests, and each has abilities of its own. They $(l)level$() as you use them. Hold Left Shift over one to open its screen and spend the points. Hold Left Alt to choose an active ability."},{"type":"patchouli:spotlight","item":"relics:magic_mirror","text":"","link_recipe":true,"anchor":"magic_mirror"},{"type":"patchouli:spotlight","item":"relics:enders_hand","text":"","link_recipe":true,"anchor":"enders_hand"},{"type":"patchouli:spotlight","item":"relics:magma_walker","text":"","link_recipe":true,"anchor":"magma_walker"}],"extra_recipe_mappings":{"relics:magic_mirror":0,"relics:enders_hand":0,"relics:magma_walker":0,"relics:horse_flute":0}},"en_us/entries/crafting/create.json":{"name":"Create","icon":"create:cogwheel","category":"patchouli:crafting","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Everything in Create turns. A water wheel or windmill spins shafts and cogwheels, and machines draw on that motion. Ask too much of a source and the whole line stalls. Engineer's Goggles show the strain."},{"type":"patchouli:text","text":"$(li)$(l:crafting/create#crafting_kinetics_mechanical_press)Mechanical Press$(/l): sheets, and compacting over a basin.$(li)$(l:crafting/create#crafting_kinetics_mechanical_press)Mechanical Mixer$(/l) over a $(l:crafting/create#crafting_kinetics_basin)Basin$(/l): mixing, some of it needing heat.$(li)$(l:crafting/create#crafting_kinetics_basin)Millstone$(/l): crushed ore, which means more metal."},{"type":"patchouli:text","text":"$(li)$(l:crafting/create#crafting_kinetics_encased_fan)Encased Fan$(/l): smelts through lava, washes through water, smokes through fire.$(br2)Hold $(l)W$() over a Create item to watch it work."},{"type":"patchouli:crafting","recipe":"create:crafting/materials/andesite_alloy","recipe2":"create:crafting/kinetics/water_wheel","anchor":"crafting_materials_andesite_alloy"},{"type":"patchouli:crafting","recipe":"create:crafting/kinetics/mechanical_press","recipe2":"create:crafting/kinetics/mechanical_mixer","anchor":"crafting_kinetics_mechanical_press"},{"type":"patchouli:crafting","recipe":"create:crafting/kinetics/basin","recipe2":"create:crafting/kinetics/millstone","anchor":"crafting_kinetics_basin"},{"type":"patchouli:crafting","recipe":"create:crafting/kinetics/encased_fan","recipe2":"create:crafting/kinetics/empty_blaze_burner","anchor":"crafting_kinetics_encased_fan"}],"extra_recipe_mappings":{"create:andesite_alloy":0,"create:mechanical_press":0,"create:mechanical_mixer":0,"create:basin":0,"create:millstone":0,"create:encased_fan":0}},"en_us/entries/crafting/create2.json":{"name":"Create: Brass","icon":"create:brass_ingot","category":"patchouli:crafting","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Copper and zinc mixed over heat make $(l:crafting/create2#brass_ingot)brass$(/l), and brass makes the clever parts: the $(l:crafting/create2#crafting_kinetics_deployer)Deployer$(/l), the $(l:crafting/create2#crafting_kinetics_deployer)Mechanical Arm$(/l), belts and $(l:crafting/create2#crafting_kinetics_belt_connector)Depots$(/l), and sequenced assembly lines for precision work."},{"type":"patchouli:text","text":"A Blaze Burner needs a blaze. Right-click one with an empty burner."},{"type":"patchouli:spotlight","item":"create:brass_ingot","text":"","link_recipe":true,"anchor":"brass_ingot"},{"type":"patchouli:crafting","recipe":"create:crafting/kinetics/deployer","recipe2":"create:crafting/kinetics/mechanical_arm","anchor":"crafting_kinetics_deployer"},{"type":"patchouli:crafting","recipe":"create:crafting/kinetics/belt_connector","recipe2":"create:crafting/kinetics/depot","anchor":"crafting_kinetics_belt_connector"}],"extra_recipe_mappings":{"create:brass_ingot":0,"create:deployer":0,"create:depot":0,"create:blaze_burner":0}},"en_us/entries/crafting/smeltery.json":{"name":"Tinkers' Smeltery","icon":"tconstruct:grout","category":"patchouli:crafting","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Tinkers' metal tools need a smeltery.$(br2)1. Smelt $(l:crafting/smeltery#smeltery_seared_grout)Grout$(/l) into seared bricks.$(br)2. A $(l:crafting/smeltery#smeltery_seared_grout)Seared Melter$(/l) will get you started."},{"type":"patchouli:text","text":"3. Cast a $(l:crafting/smeltery#smeltery_controller)Smeltery Controller$(/l) from molten copper over seared bricks, then wall it in with seared bricks, a drain and a lava tank.$(br)4. Pour through a $(l:crafting/smeltery#smeltery_seared_faucet)Faucet$(/l) into a $(l:crafting/smeltery#smeltery_seared_faucet)Casting Table$(/l) or basin.$(br2)The $(l:crafting/smeltery#foundry_controller)Foundry$(/l), built from scorched bricks, does the same and gives back byproducts."},{"type":"patchouli:spotlight","item":"tconstruct:smeltery_controller","text":"","link_recipe":true,"anchor":"smeltery_controller"},{"type":"patchouli:crafting","recipe":"tconstruct:smeltery/seared/grout","recipe2":"tconstruct:smeltery/seared/melter","anchor":"smeltery_seared_grout"},{"type":"patchouli:crafting","recipe":"tconstruct:smeltery/seared/faucet","recipe2":"tconstruct:smeltery/seared/table","anchor":"smeltery_seared_faucet"},{"type":"patchouli:spotlight","item":"tconstruct:foundry_controller","text":"","link_recipe":true,"anchor":"foundry_controller"},{"type":"patchouli:crafting","recipe":"tconstruct:common/materials_and_you","title":"Further Reading","text":"The $(l)Materials and You$() goes deeper. The smeltery has books of its own.","anchor":"common_materials_and_you"}],"extra_recipe_mappings":{"tconstruct:grout":0,"tconstruct:seared_melter":0,"tconstruct:seared_faucet":0}},"en_us/entries/crafting/tools.json":{"name":"Tinkers' Tools","icon":"tconstruct:pickaxe","category":"patchouli:crafting","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"A Tinkers tool is the sum of its parts, and every material brings its own traits. Carve parts at a $(l:crafting/tools#tables_pattern)Part Builder$(/l), cast metal ones in the smeltery, assemble them at a $(l:crafting/tools#tables_tinker_station)Tinker Station$(/l)."},{"type":"patchouli:text","text":"$(l)Modifiers$() add the rest. Tools level up as you use them and earn more slots.$(br2)$(l:crafting/tools#cobalt_ingot)Cobalt$(/l) from the Nether opens the way to $(l:crafting/tools#manyullyn_ingot)Manyullyn$(/l) and $(l:crafting/tools#hepatizon_ingot)Hepatizon$(/l)."},{"type":"patchouli:crafting","recipe":"tconstruct:tables/pattern","recipe2":"tconstruct:tables/part_builder","anchor":"tables_pattern"},{"type":"patchouli:crafting","recipe":"tconstruct:tables/tinker_station","anchor":"tables_tinker_station"},{"type":"patchouli:spotlight","item":"tconstruct:cobalt_ingot","text":"Mined in the Nether.","link_recipe":true,"anchor":"cobalt_ingot"},{"type":"patchouli:spotlight","item":"tconstruct:manyullyn_ingot","text":"Cobalt and ancient debris, alloyed in the smeltery.","link_recipe":true,"anchor":"manyullyn_ingot"},{"type":"patchouli:spotlight","item":"tconstruct:hepatizon_ingot","text":"Copper, cobalt and quartz, alloyed in the smeltery.","link_recipe":true,"anchor":"hepatizon_ingot"},{"type":"patchouli:crafting","recipe":"tconstruct:common/materials_and_you","title":"Further Reading","text":"The $(l)Materials and You$() goes deeper. The smeltery has books of its own.","anchor":"common_materials_and_you"}],"extra_recipe_mappings":{"tconstruct:pattern":0,"tconstruct:part_builder":0,"tconstruct:tinker_station":0,"tconstruct:cobalt_ingot":0,"tconstruct:manyullyn_ingot":0}},"en_us/entries/realms/aether.json":{"name":"The Aether","icon":"aether:ambrosium_shard","category":"patchouli:realms","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Build a frame of $(l)glowstone$() and pour water into it."},{"type":"patchouli:text","text":"The Aether is a realm of floating islands. Mind the edges. Tools climb from skyroot and holystone to $(l:realms/aether#zanite_gemstone)Zanite$(/l) and gravitite. $(l:realms/aether#ambrosium_shard)Ambrosium$(/l) fuels the $(l:realms/aether#altar)Altar$(/l), and $(l:realms/aether#enchanted_gravitite)Enchanted Gravitite$(/l) makes the finest gear.$(br2)Three dungeons, each with a guardian and a key: $(l:realms/aether#bronze_dungeon_key)Bronze Key$(/l), $(l:realms/aether#silver_dungeon_key)Silver Key$(/l), $(l:realms/aether#gold_dungeon_key)Gold Key$(/l)."},{"type":"patchouli:spotlight","item":"aether:zanite_gemstone","text":"","link_recipe":true,"anchor":"zanite_gemstone"},{"type":"patchouli:spotlight","item":"aether:ambrosium_shard","text":"","link_recipe":true,"anchor":"ambrosium_shard"},{"type":"patchouli:spotlight","item":"aether:altar","text":"Enchants Aether gear, fuelled by ambrosium.","link_recipe":true,"anchor":"altar"},{"type":"patchouli:spotlight","item":"aether:enchanted_gravitite","text":"","link_recipe":true,"anchor":"enchanted_gravitite"},{"type":"patchouli:spotlight","item":"aether:bronze_dungeon_key","text":"","link_recipe":true,"anchor":"bronze_dungeon_key"},{"type":"patchouli:spotlight","item":"aether:silver_dungeon_key","text":"","link_recipe":true,"anchor":"silver_dungeon_key"},{"type":"patchouli:spotlight","item":"aether:gold_dungeon_key","text":"","link_recipe":true,"anchor":"gold_dungeon_key"}],"extra_recipe_mappings":{"aether:altar":0,"aether:zanite_gemstone":0,"aether:ambrosium_shard":0,"aether:enchanted_gravitite":0}},"en_us/entries/realms/aether2.json":{"name":"Aether Add-ons","icon":"deep_aether:skyjade","category":"patchouli:realms","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(l)Deep Aether$() adds new lands, $(l:realms/aether2#skyjade)Skyjade$(/l), the $(l:realms/aether2#combiner)Combiner$(/l), and a Brass Dungeon whose storm guards a $(l:realms/aether2#brass_dungeon_key)Brass Key$(/l). Beat a boss without being touched and it gives a little more."},{"type":"patchouli:text","text":"$(l)The Aether: Redux$() brings more biomes and $(l:realms/aether2#veridium_ingot)Veridium$(/l)."},{"type":"patchouli:spotlight","item":"deep_aether:skyjade","text":"","link_recipe":true,"anchor":"skyjade"},{"type":"patchouli:spotlight","item":"deep_aether:combiner","text":"","link_recipe":true,"anchor":"combiner"},{"type":"patchouli:spotlight","item":"deep_aether:brass_dungeon_key","text":"","link_recipe":true,"anchor":"brass_dungeon_key"},{"type":"patchouli:spotlight","item":"aether_redux:veridium_ingot","text":"","link_recipe":true,"anchor":"veridium_ingot"}],"extra_recipe_mappings":{"deep_aether:skyjade":0,"deep_aether:combiner":0,"aether_redux:veridium_ingot":0}},"en_us/entries/realms/alexscaves.json":{"name":"Alex's Caves","icon":"alexscaves:azure_neodymium_ingot","category":"patchouli:realms","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Six strange biomes hide deep underground: magnetic caves, primordial caves full of dinosaurs, toxic caves, a flooded abyss, the Candy Cavity, and the Forlorn Hollows, which you may wish you hadn't found."},{"type":"patchouli:text","text":"Underground cabins hold $(l:realms/alexscaves#cave_tablet)Cave Tablets$(/l) and a $(l:realms/alexscaves#spelunkery_table)Spelunkery Table$(/l) to translate them."},{"type":"patchouli:spotlight","item":"alexscaves:cave_tablet","text":"","link_recipe":true,"anchor":"cave_tablet"},{"type":"patchouli:spotlight","item":"alexscaves:spelunkery_table","text":"","link_recipe":true,"anchor":"spelunkery_table"},{"type":"patchouli:spotlight","item":"alexscaves:azure_neodymium_ingot","text":"","link_recipe":true,"anchor":"azure_neodymium_ingot"}]},"en_us/entries/realms/otherside.json":{"name":"The Otherside","icon":"deeperdarker:heart_of_the_deep","category":"patchouli:realms","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Below the Deep Dark lies the $(l)Otherside$(). Ancient Cities hold its portal frame. The Warden carries the $(l:realms/otherside#heart_of_the_deep)Heart of the Deep$(/l) that lights it."},{"type":"patchouli:text","text":"$(l)Warden$() and $(l)Resonarium$() gear come from there, and Warden armor can be smithed into Cataclysm's Ignitium or Cursium later."},{"type":"patchouli:spotlight","item":"deeperdarker:heart_of_the_deep","text":"Dropped by the Warden. It lights the Otherside portal.","link_recipe":true,"anchor":"heart_of_the_deep"},{"type":"patchouli:spotlight","item":"deeperdarker:soul_crystal","text":"","link_recipe":true,"anchor":"soul_crystal"}],"extra_recipe_mappings":{"deeperdarker:heart_of_the_deep":0,"deeperdarker:soul_crystal":0}},"en_us/entries/realms/twilight.json":{"name":"The Twilight Forest","icon":"twilightforest:magic_map","category":"patchouli:realms","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Dig a small pool, ring it with flowers, and throw in a diamond.$(br2)The Twilight Forest has to be taken in order."},{"type":"patchouli:text","text":"Lands you haven't earned will curse you until the boss before them is dead: the Naga and the Lich, the Minoshroom and the Hydra, the Knight Phantoms and the Ur-Ghast, the Alpha Yeti and the Snow Queen.$(br2)A $(l:realms/twilight#magic_map)Magic Map$(/l) shows the way."},{"type":"patchouli:spotlight","item":"twilightforest:magic_map","text":"","link_recipe":true,"anchor":"magic_map"},{"type":"patchouli:spotlight","item":"twilightforest:fiery_ingot","text":"Fiery blood from the Hydra plus iron.","link_recipe":true,"anchor":"fiery_ingot"},{"type":"patchouli:spotlight","item":"twilightforest:knightmetal_ingot","text":"From the Knight Phantoms' stronghold.","link_recipe":true,"anchor":"knightmetal_ingot"}],"extra_recipe_mappings":{"twilightforest:magic_map":0,"twilightforest:fiery_ingot":0,"twilightforest:knightmetal_ingot":0}},"en_us/entries/travel/backpacks.json":{"name":"Backpacks","icon":"sophisticatedbackpacks:backpack","category":"patchouli:travel","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Backpacks come in leather, iron, gold, diamond and netherite. Upgrading one keeps everything inside.$(br2)Wear it and press B, or sneak and set it down. Upgrades pick up, pull in, feed you, craft, and stack deeper."},{"type":"patchouli:crafting","recipe":"sophisticatedbackpacks:backpack","recipe2":"sophisticatedbackpacks:iron_backpack","anchor":"backpack"},{"type":"patchouli:crafting","recipe":"sophisticatedbackpacks:gold_backpack","recipe2":"sophisticatedbackpacks:diamond_backpack","anchor":"gold_backpack"},{"type":"patchouli:crafting","recipe":"sophisticatedbackpacks:upgrade_base","recipe2":"sophisticatedbackpacks:pickup_upgrade","anchor":"upgrade_base"},{"type":"patchouli:crafting","recipe":"sophisticatedbackpacks:magnet_upgrade","recipe2":"sophisticatedbackpacks:feeding_upgrade","anchor":"magnet_upgrade"}],"extra_recipe_mappings":{"sophisticatedbackpacks:backpack":0,"sophisticatedbackpacks:iron_backpack":0,"sophisticatedbackpacks:pickup_upgrade":0,"sophisticatedbackpacks:magnet_upgrade":0,"sophisticatedbackpacks:feeding_upgrade":0,"sophisticatedbackpacks:crafting_upgrade":0}},"en_us/entries/travel/chunks.json":{"name":"Claims and Mining","icon":"minecraft:filled_map","category":"patchouli:travel","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)FTB Chunks$(): claim land on the map. Claimed chunks are yours, and can stay loaded while you're away.$(li)$(l)FTB Ultimine$(): hold the key while mining to take a whole vein or tree at once. Hungry work."},{"type":"patchouli:text","text":"$(li)$(l:travel/chunks#elevator_white)Elevators$(/l): stack two in a column. Jump to rise, sneak to drop."},{"type":"patchouli:spotlight","item":"elevatorid:elevator_white,elevatorid:elevator_orange,elevatorid:elevator_magenta,elevatorid:elevator_light_blue,elevatorid:elevator_yellow,elevatorid:elevator_lime,elevatorid:elevator_pink,elevatorid:elevator_gray,elevatorid:elevator_light_gray,elevatorid:elevator_cyan,elevatorid:elevator_purple,elevatorid:elevator_blue,elevatorid:elevator_brown,elevatorid:elevator_green,elevatorid:elevator_red,elevatorid:elevator_black","text":"","link_recipe":true,"anchor":"elevator_white"}]},"en_us/entries/travel/paragliders.json":{"name":"Paragliders","icon":"paraglider:paraglider","category":"patchouli:travel","sortnum":4,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Hold a $(l:travel/paragliders#paraglider)Paraglider$(/l) as you fall and you'll glide. Rising heat from a fire will carry you up."},{"type":"patchouli:text","text":"Gliding wears down your stamina. $(l:travel/paragliders#spirit_orb)Spirit Orbs$(/l) turn up in chests and broken spawners. Bring four to a $(l:travel/paragliders#goddess_statue)Goddess Statue$(/l), usually near a village, for a $(l:travel/paragliders#heart_container)Heart Container$(/l) or a $(l:travel/paragliders#stamina_vessel)Stamina Vessel$(/l)."},{"type":"patchouli:spotlight","item":"paraglider:paraglider","text":"","link_recipe":true,"anchor":"paraglider"},{"type":"patchouli:spotlight","item":"paraglider:spirit_orb","text":"From spawners and loot.","link_recipe":true,"anchor":"spirit_orb"},{"type":"patchouli:spotlight","item":"paraglider:goddess_statue","text":"Trades Spirit Orbs for vessels.","link_recipe":true,"anchor":"goddess_statue"},{"type":"patchouli:spotlight","item":"paraglider:heart_container","text":"One more heart.","link_recipe":true,"anchor":"heart_container"},{"type":"patchouli:spotlight","item":"paraglider:stamina_vessel","text":"More stamina.","link_recipe":true,"anchor":"stamina_vessel"}],"extra_recipe_mappings":{"paraglider:paraglider":0,"paraglider:spirit_orb":0,"paraglider:heart_container":0,"paraglider:stamina_vessel":0}},"en_us/entries/travel/ships.json":{"name":"Ships and Trains","icon":"smallships:oak_cog","category":"patchouli:travel","sortnum":5,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(l)Small Ships$() brings real sailing ships: the sturdy $(l:travel/ships#dockyard)Cog$(/l) and Brigg, the oared Galley, the Dhow, and the shield-hung Drakkar."},{"type":"patchouli:text","text":"Ships are raised at a $(l:travel/ships#dockyard)Dockyard$(/l) by the water. Feed it materials and it builds the hull. $(l:travel/ships#cotton_sails)Cotton Sails$(/l) and other fittings go on there too. Mount $(l:travel/ships#cannon)Cannons$(/l) and keep $(l:travel/ships#cannon_ball)Cannon Balls$(/l) aboard. Mind the wind and your cargo."},{"type":"patchouli:text","text":"On land, $(l)Steam 'n' Rails$() gives Create trains new tracks, bogeys and $(l:travel/ships#fuel_tank)Fuel Tanks$(/l)."},{"type":"patchouli:spotlight","item":"smallships:dockyard","text":"Builds and upgrades ships.","link_recipe":true,"anchor":"dockyard"},{"type":"patchouli:spotlight","item":"smallships:cotton_sails","text":"","link_recipe":true,"anchor":"cotton_sails"},{"type":"patchouli:spotlight","item":"smallships:cannon","text":"Mounts on the side of a ship.","link_recipe":true,"anchor":"cannon"},{"type":"patchouli:spotlight","item":"smallships:cannon_ball","text":"","link_recipe":true,"anchor":"cannon_ball"},{"type":"patchouli:spotlight","item":"railways:fuel_tank","text":"Fuel storage for Create trains.","link_recipe":true,"anchor":"fuel_tank"}],"extra_recipe_mappings":{"smallships:dockyard":0,"smallships:cannon":0,"smallships:cannon_ball":0,"smallships:cotton_sails":0}},"en_us/entries/travel/storage.json":{"name":"Storage","icon":"sophisticatedstorage:chest","category":"patchouli:travel","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(li)$(l)Sophisticated Storage$(): chests and barrels you upgrade where they stand. A $(l:travel/storage#controller)Storage Controller$(/l) reaches every one connected to it."},{"type":"patchouli:text","text":"$(li)$(l)Ender Storage$(): match the three colours and chests share one inventory, across any distance.$(li)$(l)Lootr$(): every dungeon chest holds its own loot for each player."},{"type":"patchouli:spotlight","item":"sophisticatedstorage:chest","text":"","link_recipe":true,"anchor":"chest"},{"type":"patchouli:spotlight","item":"sophisticatedstorage:controller","text":"Links nearby Sophisticated Storage chests and barrels into one inventory.","link_recipe":true,"anchor":"controller"}],"extra_recipe_mappings":{"sophisticatedstorage:chest":0,"sophisticatedstorage:barrel":0,"sophisticatedstorage:controller":0}},"en_us/entries/travel/waystones.json":{"name":"Waystones","icon":"waystones:waystone","category":"patchouli:travel","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Activate a $(l:travel/waystones#waystone)Waystone$(/l) and you can return to it from any other. The farther you go, the more experience it costs."},{"type":"patchouli:text","text":"A $(l:travel/waystones#waystone)Warp Stone$(/l) does the same from your pocket. $(l:travel/waystones#return_scroll)Return Scrolls$(/l) and $(l:travel/waystones#return_scroll)Warp Scrolls$(/l) are one-way tickets. $(l:travel/waystones#sharestone)Sharestones$(/l) only link to others of their colour."},{"type":"patchouli:crafting","recipe":"waystones:waystone","recipe2":"waystones:warp_stone","anchor":"waystone"},{"type":"patchouli:crafting","recipe":"waystones:return_scroll","recipe2":"waystones:warp_scroll","anchor":"return_scroll"},{"type":"patchouli:spotlight","item":"waystones:sharestone","text":"Sharestones only link to other sharestones of the same colour.","link_recipe":true,"anchor":"sharestone"}],"extra_recipe_mappings":{"waystones:waystone":0,"waystones:warp_stone":0,"waystones:return_scroll":0,"waystones:warp_scroll":0,"waystones:sharestone":0}},"en_us/entries/bees/bumblezone.json":{"name":"The Bumblezone","icon":"minecraft:bee_nest","category":"patchouli:bees","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Somewhere inside the bee nests is a whole other world. Throw an ender pearl at a nest to find it."},{"type":"patchouli:text","text":"Don't anger the bees. $(l:bees/bumblezone#honey_compass)Honey Compasses$(/l) lead to its structures, and the rarest ones lead to the $(l)Bee Queen$(), who trades if you bring what she wants.$(br2)Fall through the bottom to get home."},{"type":"patchouli:spotlight","item":"the_bumblezone:honey_compass","text":"","link_recipe":true,"anchor":"honey_compass"}]},"en_us/entries/bees/productive.json":{"name":"Productive Bees","icon":"minecraft:beehive","category":"patchouli:bees","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Different bees make combs of different things, from honey to diamonds."},{"type":"patchouli:text","text":"Solitary bees live in nests out in the world. They won't live in a hive and make nothing themselves; they're for breeding. Set a nest in the right biome and feed it Honey Treats, and a new bee moves in."},{"type":"patchouli:text","text":"Productive bees live in an Advanced Beehive, and a Centrifuge spins their combs apart. Most come from breeding, and the Big Book of Bees knows every pairing. If a bee won't settle, check its flowers and the weather."},{"type":"patchouli:crafting","recipe":"productivebees:guide_book","title":"Further Reading","text":"The $(l)Big Book of Bees$() goes deeper.","anchor":"guide_book"}]},"en_us/entries/dragons/dragons.json":{"name":"Dragons","icon":"iceandfire:dragonscales_blue","category":"patchouli:dragons","sortnum":0,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Fire dragons nest where it's warm, ice dragons where it's cold, lightning dragons in jungles and badlands. Young ones keep roosts on the surface. The old ones sleep in caves, on bigger hoards."},{"type":"patchouli:text","text":"No wild dragon can be tamed. The $(l:dragons/dragons#bestiary)Bestiary$(/l) fills in the rest."},{"type":"patchouli:spotlight","item":"iceandfire:bestiary","text":"","link_recipe":true,"anchor":"bestiary"},{"type":"patchouli:crafting","recipe":"iceandfire:bestiary","title":"Further Reading","text":"The $(l)Bestiary$() goes deeper.","anchor":"bestiary_2"}],"extra_recipe_mappings":{"iceandfire:bestiary":0,"iceandfire:dragonscales_blue":0}},"en_us/entries/dragons/drops.json":{"name":"What Dragons Drop","icon":"iceandfire:dragonbone","category":"patchouli:dragons","sortnum":1,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"A dragon leaves scales, flesh, bones, a skull and its heart. Bottle its blood before you carve it, but take too much and the scales and heart are lost."},{"type":"patchouli:text","text":"Scale armor resists that dragon's element. Bones dipped in blood make elemental weapons."},{"type":"patchouli:crafting","recipe":"iceandfire:dragonbone_sword","anchor":"dragonbone_sword"},{"type":"patchouli:crafting","recipe":"iceandfire:bestiary","title":"Further Reading","text":"The $(l)Bestiary$() goes deeper.","anchor":"bestiary"}],"extra_recipe_mappings":{"iceandfire:dragonbone":0}},"en_us/entries/dragons/eggs.json":{"name":"Raising a Dragon","icon":"iceandfire:dragonegg_red","category":"patchouli:dragons","sortnum":3,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"Grown females, stage 4 or 5, carry eggs. Bottle their blood and the eggs are lost. Fire eggs hatch in fire, ice eggs in water, lightning eggs in the rain."},{"type":"patchouli:text","text":"The hatchling is yours alone. Feed it, raise it, saddle it when it's big enough, and keep a $(l:dragons/eggs#dragon_horn)Dragon Horn$(/l) for when you need to carry it."},{"type":"patchouli:crafting","recipe":"iceandfire:dragon_horn","anchor":"dragon_horn"},{"type":"patchouli:spotlight","item":"iceandfire:dragon_meal","text":"Makes young dragons grow.","link_recipe":true,"anchor":"dragon_meal"},{"type":"patchouli:crafting","recipe":"iceandfire:bestiary","title":"Further Reading","text":"The $(l)Bestiary$() goes deeper.","anchor":"bestiary"}],"extra_recipe_mappings":{"iceandfire:dragon_horn":0,"iceandfire:dragon_meal":0,"iceandfire:dragonegg_red":0}},"en_us/entries/dragons/forge.json":{"name":"The Dragonforge","icon":"iceandfire:dragonsteel_fire_ingot","category":"patchouli:dragons","sortnum":2,"read_by_default":true,"pages":[{"type":"patchouli:text","text":"$(l:dragons/forge#dragonsteel_fire_ingot)Dragonsteel$(/l) can only be forged with a dragon's own breath.$(br2)Build a $(l:dragons/forge#dragonforge_fire_brick)Dragonforge$(/l) from $(l:dragons/forge#dragonforge_fire_brick)Dragonforge Bricks$(/l) around a $(l:dragons/forge#dragonforge_fire_brick)Core$(/l) made with a dragon heart, add an $(l:dragons/forge#dragonforge_fire_input)Aperture$(/l), and feed it an iron ingot and that dragon's blood."},{"type":"patchouli:text","text":"Then a dragon of that element, stage 3 or older, has to breathe into it."},{"type":"patchouli:spotlight","item":"iceandfire:dragonsteel_fire_ingot","text":"Made in a fire Dragonforge. Ice and lightning forges make their own kinds.","link_recipe":true,"anchor":"dragonsteel_fire_ingot"},{"type":"patchouli:crafting","recipe":"iceandfire:dragonforge_fire_brick","recipe2":"iceandfire:dragonforge_fire_core_disabled","anchor":"dragonforge_fire_brick"},{"type":"patchouli:crafting","recipe":"iceandfire:dragonforge_fire_input","title":"Dragonforge Aperture","anchor":"dragonforge_fire_input"},{"type":"patchouli:crafting","recipe":"iceandfire:bestiary","title":"Further Reading","text":"The $(l)Bestiary$() goes deeper.","anchor":"bestiary"}],"extra_recipe_mappings":{"iceandfire:dragonsteel_fire_ingot":0,"iceandfire:dragonsteel_ice_ingot":0,"iceandfire:dragonforge_fire_brick":0}}}

;(() => {
  let FileUtil = Java.loadClass('net.minecraft.FileUtil')
  let made = {}
  let written = 0
  Object.keys(FT_BOOK_FILES).forEach(rel => {
    let path = 'patchouli_books/adventure_book/' + rel
    let dir = path.substring(0, path.lastIndexOf('/'))
    try {
      if (!made[dir]) { FileUtil.createDirectoriesSafe(dir); made[dir] = true }
      JsonIO.write(path, FT_BOOK_FILES[rel])
      written++
    } catch (e) { console.error(`[Fairytale] couldn't write ${path}: ${e}`) }
  })
  console.info(`[Fairytale] Adventure Book: ${written} of ${Object.keys(FT_BOOK_FILES).length} files in place`)
})()
